PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,title TEXT NOT NULL,url TEXT NOT NULL,revision TEXT NOT NULL,rights TEXT NOT NULL,note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS works(id TEXT PRIMARY KEY,title TEXT NOT NULL,author TEXT NOT NULL,era TEXT NOT NULL,intro TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(id),status TEXT NOT NULL CHECK(status IN ('pending','approved','disputed','retired')),version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sentences(id TEXT PRIMARY KEY,work_id TEXT NOT NULL REFERENCES works(id),position INTEGER NOT NULL,text TEXT NOT NULL,source_text TEXT NOT NULL,explanation TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','approved','disputed','retired')),UNIQUE(work_id,position));
CREATE TABLE IF NOT EXISTS lexemes(id TEXT PRIMARY KEY,text TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS senses(id TEXT PRIMARY KEY,lexeme_id TEXT NOT NULL REFERENCES lexemes(id),label TEXT NOT NULL,definition TEXT NOT NULL,grammar TEXT NOT NULL,reading TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(id),note TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','approved','disputed','retired')));
CREATE TABLE IF NOT EXISTS occurrences(id TEXT PRIMARY KEY,sentence_id TEXT NOT NULL REFERENCES sentences(id),lexeme_id TEXT NOT NULL REFERENCES lexemes(id),sense_id TEXT NOT NULL REFERENCES senses(id),start INTEGER NOT NULL,end INTEGER NOT NULL,note TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','approved','disputed','retired')),CHECK(start>=0 AND end>start),UNIQUE(sentence_id,start,end));
CREATE INDEX IF NOT EXISTS occurrences_sense ON occurrences(sense_id);
CREATE INDEX IF NOT EXISTS occurrences_lexeme ON occurrences(lexeme_id);
CREATE TABLE IF NOT EXISTS questions(id TEXT PRIMARY KEY,occurrence_id TEXT NOT NULL REFERENCES occurrences(id),prompt TEXT NOT NULL,choices TEXT NOT NULL,answer INTEGER NOT NULL,explanation TEXT NOT NULL,hint TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','approved','disputed','retired')),version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS textbook_editions(id TEXT PRIMARY KEY,name TEXT NOT NULL,system TEXT NOT NULL CHECK(system='5-4'),edition TEXT NOT NULL,school_year TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(id),status TEXT NOT NULL CHECK(status IN ('pending','approved','disputed','retired')));
CREATE TABLE IF NOT EXISTS volumes(id TEXT PRIMARY KEY,edition_id TEXT NOT NULL REFERENCES textbook_editions(id),grade INTEGER NOT NULL CHECK(grade BETWEEN 1 AND 9),semester TEXT NOT NULL CHECK(semester IN ('上','下')),UNIQUE(edition_id,grade,semester));
CREATE TABLE IF NOT EXISTS memberships(id TEXT PRIMARY KEY,volume_id TEXT NOT NULL REFERENCES volumes(id),work_id TEXT NOT NULL REFERENCES works(id),unit TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('课内文言文','古诗词','课外诵读','争议')),page TEXT NOT NULL,evidence TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','approved','disputed','retired')),UNIQUE(volume_id,work_id));
CREATE TABLE IF NOT EXISTS coverage_slots(grade INTEGER NOT NULL CHECK(grade BETWEEN 1 AND 9),semester TEXT NOT NULL CHECK(semester IN ('上','下')),status TEXT NOT NULL DEFAULT '待版权页与目录',PRIMARY KEY(grade,semester));
CREATE TABLE IF NOT EXISTS content_reviews(id INTEGER PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,previous_status TEXT NOT NULL,new_status TEXT NOT NULL,reviewer TEXT NOT NULL,evidence TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS imports(digest TEXT PRIMARY KEY,version TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_records(id INTEGER PRIMARY KEY,profile TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('read','discrimination','recitation','dictation')),work_id TEXT REFERENCES works(id),sense_id TEXT REFERENCES senses(id),question_id TEXT REFERENCES questions(id),correct INTEGER CHECK(correct IN (0,1)),hinted INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,day TEXT NOT NULL,UNIQUE(profile,question_id,day));
CREATE INDEX IF NOT EXISTS learning_profile ON learning_records(profile,created_at);
CREATE TABLE IF NOT EXISTS preferences(profile TEXT PRIMARY KEY,scopes TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations(version) VALUES(1);
